#include "../../04-图论/斯坦纳树.cpp"
int main(){mt19937 r(55);for(int t=0;t<250;t++){int n=2+r()%5;vector<tuple<int,int,ll>> e;vector<vector<pair<int,ll>>> g(n);for(int i=0;i<n;i++)for(int j=0;j<i;j++)if(r()%2){ll w=r()%8;e.push_back({i,j,w});g[i].push_back({j,w});g[j].push_back({i,w});}vector<int> term;for(int i=0;i<n;i++)if(r()%2)term.push_back(i);ll best=LLONG_MAX/4;if(term.empty())best=0;else for(int mask=0;mask<(1<<(int)e.size());mask++){vector<int> p(n);iota(p.begin(),p.end(),0);auto f=[&](auto&&f,int x)->int{return p[x]==x?x:p[x]=f(f,p[x]);};ll z=0;for(int i=0;i<(int)e.size();i++)if(mask>>i&1){auto [u,v,w]=e[i];p[f(f,u)]=f(f,v);z+=w;}bool ok=true;for(int x:term)ok&=f(f,x)==f(f,term[0]);if(ok)best=min(best,z);}assert(steiner_tree(g,term)==best);}}
